{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The Pub/Sub topic does not specify a KMS key for encryption, relying on Google-managed encryption keys. Using Customer-Managed Encryption Keys (CMEK) via the `kms_key_name` attribute provides better control over data security and compliance."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_trigger\" {\n  name = \"enterprise-disaster-recovery-orchestration-platform-topic-notification\"\n\n  # CKV_GCP_83: Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)\n  # Note: Replace 'projects/my-project/locations/us-central1/keyRings/my-keyring/cryptoKeys/my-key' with your actual KMS Key ID.\n  kms_key_name = \"projects/my-project/locations/us-central1/keyRings/my-keyring/cryptoKeys/my-key\"\n}",
  "fix_summary": "Added the `kms_key_name` attribute to the `google_pubsub_topic` resource to enable Customer-Managed Encryption Keys (CMEK), addressing Checkov finding CKV_GCP_83. A placeholder KMS key path was used as no specific key was provided in the original code; this must be updated to a valid KMS key URI."
}
